export { LineChart, type LineChartProps } from "./line";
export { AreaChart, type AreaChartProps } from "./area";
export { BarChart, type BarChartProps, type BarOrientation } from "./bar";
export { ScatterChart, type ScatterChartProps } from "./scatter";
export { Donut, Share, type DonutProps, type ShareProps, type ShareSlice } from "./donut";
export { Histogram, type HistogramProps, type HistogramBin } from "./histogram";
export { SmallMultiples, type SmallMultiplesProps, type SmallMultiple } from "./multiples";
export { Sparkline, type SparklineProps } from "./sparkline";
export type { ChartSeries, ChartAnnotation, ChartPoint } from "./frame";

"use client";

import * as React from "react";
import {
  ChartField,
  ChartHead,
  ChartLegend,
  ChartLegendItem,
  ChartTip,
  ChartTitle,
  LegendSwatch,
  MAX_SERIES,
  PLOT,
  SrTable,
  areaMark,
  chartStyles,
  defaultFormat,
  lineMark,
  niceMax,
  stackedRows,
  ticksFor,
  type ChartAnnotation,
  type ChartSeries,
} from "./frame";
import { rs } from "../rs";

export interface LineChartProps extends React.HTMLAttributes<HTMLDivElement> {
  series: ChartSeries[];
  labels?: string[];
  height?: number;
  /** Fill under the first series. Prefer AreaChart for a dedicated area. */
  area?: boolean;
  stacked?: boolean;
  inverted?: boolean;
  grid?: boolean;
  ticks?: number;
  unit?: string;
  yLabel?: string;
  xLabel?: string;
  annotations?: ChartAnnotation[];
  domain?: [number, number];
  spot?: boolean | string;
  valueFormat?: (value: number) => string;
}

export function LineChart({
  series,
  labels,
  height = 204,
  area,
  stacked,
  inverted,
  grid = true,
  ticks = 4,
  unit,
  yLabel,
  xLabel,
  annotations,
  domain,
  spot,
  valueFormat,
  className,
  ...props
}: LineChartProps) {
  const shown = series.slice(0, MAX_SERIES);
  const n = Math.max(1, ...shown.map((s) => s.values.length));
  const stacks = stacked ? stackedRows(shown) : null;
  const rawMax = stacks
    ? Math.max(...stacks.map((row) => row[row.length - 1] ?? 0))
    : Math.max(0, ...shown.flatMap((s) => s.values));
  const max = domain?.[1] ?? niceMax(rawMax);
  const min = domain?.[0] ?? 0;
  const span = max - min || 1;
  const format = valueFormat ?? ((v: number) => defaultFormat(v));
  const tip = valueFormat ?? ((v: number) => defaultFormat(v, unit));
  const [hover, setHover] = React.useState<number | null>(null);
  const overlayRef = React.useRef<SVGRectElement>(null);

  const { W, ML, MR, MT, MB } = PLOT;
  const plotW = W - ML - MR;
  const plotH = height - MT - MB;
  const x = (i: number) => ML + (n <= 1 ? 0 : (i / (n - 1)) * plotW);
  const y = (v: number) => {
    const t = (v - min) / span;
    return inverted ? MT + t * plotH : MT + plotH - t * plotH;
  };
  const path = (values: number[]) => values.map((v, i) => `${i === 0 ? "M" : "L"}${x(i)} ${y(v)}`).join(" ");
  const tickVals = ticksFor(max, ticks);
  const tickLabels = labels ?? Array.from({ length: n }, (_, i) => `${i + 1}`);

  const locate = (clientX: number): number | null => {
    const rect = overlayRef.current?.getBoundingClientRect();
    if (!rect || rect.width === 0) return null;
    const ratio = Math.min(1, Math.max(0, (clientX - rect.left) / rect.width));
    return Math.round(ratio * (n - 1));
  };

  const svg = rs(["rs-chart-svg"], chartStyles.svg);
  const plot = rs(["rs-chart-plot"], chartStyles.plot);
  const gridSx = rs(["rs-chart-grid"], chartStyles.grid);
  const axis = rs(["rs-chart-axis"], chartStyles.axis);
  const baseline = rs(["rs-chart-baseline"], chartStyles.baseline);
  const cursor = rs(["rs-chart-cursor"], chartStyles.cursor);
  const ann = rs(["rs-chart-ann"], chartStyles.ann);
  const dot = rs(["rs-chart-dot"], chartStyles.dot);

  return (
    <ChartField spot={spot} className={className} {...props}>
      {(yLabel || xLabel) && (
        <ChartHead>
          {yLabel ? <ChartTitle>{yLabel}</ChartTitle> : <span />}
          {xLabel ? <ChartTitle>{xLabel}</ChartTitle> : null}
        </ChartHead>
      )}
      <svg
        className={svg.className}
        style={svg.style}
        viewBox={`0 0 ${W} ${height}`}
        role="img"
        aria-label={`Line chart, ${shown.map((s) => s.name).join(" and ")}`}
      >
        <g className={plot.className} style={plot.style}>
          {grid &&
            tickVals.map((t) => (
              <g key={t}>
                <line className={gridSx.className} style={gridSx.style} x1={ML} x2={W - MR} y1={y(t)} y2={y(t)} />
                <text className={axis.className} style={axis.style} x={ML - 6} y={y(t) + 3.5} textAnchor="end">
                  {format(t)}
                </text>
              </g>
            ))}
          <line className={baseline.className} style={baseline.style} x1={ML} x2={W - MR} y1={y(min)} y2={y(min)} />
          {area && shown[0] && !stacked && (
            <path {...areaMark(Boolean(spot))} d={`${path(shown[0].values)} L${x(n - 1)} ${y(min)} L${x(0)} ${y(min)} Z`} />
          )}
          {stacked && stacks
            ? shown.map((s, si) => {
                const top = stacks.map((row) => row[si] ?? 0);
                return <path key={s.name} {...lineMark(si, Boolean(spot))} d={path(top)} />;
              })
            : shown.map((s, si) => <path key={s.name} {...lineMark(si, Boolean(spot))} d={path(s.values)} />)}
          {annotations?.map((a) => (
            <g key={`${a.at}-${a.label}`}>
              <line className={cursor.className} style={cursor.style} x1={x(a.at)} x2={x(a.at)} y1={MT} y2={y(min)} />
              <text className={ann.className} style={ann.style} x={x(a.at) + 4} y={MT + 10}>
                {a.label}
              </text>
            </g>
          ))}
          {hover != null && (
            <g>
              <line className={cursor.className} style={cursor.style} x1={x(hover)} x2={x(hover)} y1={MT} y2={y(min)} />
              {shown.map((s, si) => (
                <circle
                  key={si}
                  className={dot.className}
                  style={dot.style}
                  cx={x(hover)}
                  cy={y(stacked && stacks ? (stacks[hover]?.[si] ?? 0) : (s.values[hover] ?? 0))}
                  r={3}
                />
              ))}
            </g>
          )}
          <text className={axis.className} style={axis.style} x={ML} y={height - 4} textAnchor="start">
            {tickLabels[0]}
          </text>
          <text className={axis.className} style={axis.style} x={W - MR} y={height - 4} textAnchor="end">
            {tickLabels[n - 1]}
          </text>
          <rect
            ref={overlayRef}
            x={ML}
            y={0}
            width={plotW}
            height={height}
            fill="transparent"
            onMouseMove={(e) => setHover(locate(e.clientX))}
            onMouseLeave={() => setHover(null)}
          />
        </g>
      </svg>
      {hover != null && (
        <ChartTip
          left={`${(x(hover) / W) * 100}%`}
          top={`${(MT / height) * 100}%`}
          label={tickLabels[hover] ?? ""}
          rows={shown.map((s) => ({ name: s.name, value: tip(s.values[hover] ?? 0) }))}
        />
      )}
      {(shown.length > 1 || unit) && (
        <ChartLegend>
          {shown.map((s, si) => (
            <ChartLegendItem key={s.name}>
              <LegendSwatch seriesIndex={si} spot={Boolean(spot)} />
              {s.name}
            </ChartLegendItem>
          ))}
          {unit ? <ChartLegendItem>{unit}</ChartLegendItem> : null}
        </ChartLegend>
      )}
      <SrTable caption="Chart data" labels={tickLabels} series={shown} />
    </ChartField>
  );
}

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster } from "../tokens.stylex";
import { LineChart, type LineChartProps } from "./line";

const styles = stylex.create({
  area: {
    borderRadius: 0,
    boxShadow: "none",
    backgroundColor: raster.paper,
  },
});

export type AreaChartProps = Omit<LineChartProps, "area">;

/** Filled field. Same law as the line: hairlines, texture, one optional spot. */
export function AreaChart(props: AreaChartProps) {
  void styles.area;
  return <LineChart {...props} area />;
}

"use client";

import * as React from "react";
import {
  ChartField,
  ChartHead,
  ChartLegend,
  ChartLegendItem,
  ChartTip,
  ChartTitle,
  PLOT,
  SrTable,
  barMark,
  chartStyles,
  defaultFormat,
  niceMax,
  stackedRows,
  ticksFor,
  type ChartSeries,
} from "./frame";
import { rs } from "../rs";

export type BarOrientation = "vertical" | "horizontal";

export interface BarChartProps extends React.HTMLAttributes<HTMLDivElement> {
  data?: Array<{ label: string; value: number }>;
  series?: ChartSeries[];
  labels?: string[];
  height?: number;
  orientation?: BarOrientation;
  stacked?: boolean;
  inverted?: boolean;
  grid?: boolean;
  ticks?: number;
  unit?: string;
  yLabel?: string;
  spot?: boolean | string;
  valueFormat?: (value: number) => string;
}

export function BarChart({
  data,
  series,
  labels,
  height = 204,
  orientation = "vertical",
  stacked,
  inverted,
  grid = true,
  ticks = 4,
  unit,
  yLabel,
  spot,
  valueFormat,
  className,
  ...props
}: BarChartProps) {
  const fromData: ChartSeries[] = data ? [{ name: "Value", values: data.map((d) => d.value) }] : [];
  const shown = (series ?? fromData).slice(0, 4);
  const tickLabels = labels ?? data?.map((d) => d.label) ?? shown[0]?.values.map((_, i) => `${i + 1}`) ?? [];
  const n = tickLabels.length;
  const stacks = stacked && shown.length > 1 ? stackedRows(shown) : null;
  const rawMax = stacks
    ? Math.max(...stacks.map((row) => row[row.length - 1] ?? 0))
    : Math.max(0, ...shown.flatMap((s) => s.values));
  const max = niceMax(rawMax);
  const format = valueFormat ?? ((v: number) => defaultFormat(v));
  const tip = valueFormat ?? ((v: number) => defaultFormat(v, unit));
  const [hover, setHover] = React.useState<number | null>(null);

  const { W, ML, MR, MT, MB } = PLOT;
  const plotW = W - ML - MR;
  const plotH = height - MT - MB;
  const horizontal = orientation === "horizontal";
  const band = (horizontal ? plotH : plotW) / Math.max(1, n);
  const barThick = Math.min(8, Math.max(2, band - 1));
  const inset = (band - barThick) / 2;
  const yV = (v: number) => {
    const t = v / max;
    return inverted ? MT + t * plotH : MT + plotH - t * plotH;
  };
  const xV = (v: number) => ML + (v / max) * plotW;
  const tickVals = ticksFor(max, ticks);
  const labelEvery = Math.ceil(n / 8);

  const svg = rs(["rs-chart-svg"], chartStyles.svg);
  const plot = rs(["rs-chart-plot"], chartStyles.plot);
  const gridSx = rs(["rs-chart-grid"], chartStyles.grid);
  const axis = rs(["rs-chart-axis"], chartStyles.axis);
  const baseline = rs(["rs-chart-baseline"], chartStyles.baseline);

  return (
    <ChartField spot={spot} className={className} {...props}>
      {yLabel && (
        <ChartHead>
          <ChartTitle>{yLabel}</ChartTitle>
        </ChartHead>
      )}
      <svg className={svg.className} style={svg.style} viewBox={`0 0 ${W} ${height}`} role="img" aria-label="Bar chart">
        <g className={plot.className} style={plot.style}>
          {grid &&
            tickVals.map((t) =>
              horizontal ? (
                <g key={t}>
                  <line className={gridSx.className} style={gridSx.style} x1={xV(t)} x2={xV(t)} y1={MT} y2={height - MB} />
                  <text className={axis.className} style={axis.style} x={xV(t)} y={height - 4} textAnchor="middle">
                    {format(t)}
                  </text>
                </g>
              ) : (
                <g key={t}>
                  <line className={gridSx.className} style={gridSx.style} x1={ML} x2={W - MR} y1={yV(t)} y2={yV(t)} />
                  <text className={axis.className} style={axis.style} x={ML - 6} y={yV(t) + 3.5} textAnchor="end">
                    {format(t)}
                  </text>
                </g>
              ),
            )}
          {tickLabels.map((label, i) => {
            const values = shown.map((s) => s.values[i] ?? 0);
            const mark = (si: number) =>
              barMark({
                spot: Boolean(spot) && (stacks ? si === 0 : true),
                muted: hover != null && hover !== i,
              });
            if (horizontal) {
              const y0 = MT + i * band + inset;
              if (stacks) {
                let prev = 0;
                return shown.map((s, si) => {
                  const v = s.values[i] ?? 0;
                  const x1 = xV(prev);
                  const x2 = xV(prev + v);
                  prev += v;
                  return (
                    <rect
                      key={`${label}-${s.name}`}
                      {...mark(si)}
                      x={x1}
                      y={y0}
                      width={Math.max(0, x2 - x1)}
                      height={barThick}
                      onMouseEnter={() => setHover(i)}
                      onMouseLeave={() => setHover(null)}
                    />
                  );
                });
              }
              const v = values[0] ?? 0;
              return (
                <rect
                  key={label}
                  {...mark(0)}
                  x={ML}
                  y={y0}
                  width={Math.max(0, xV(v) - ML)}
                  height={barThick}
                  onMouseEnter={() => setHover(i)}
                  onMouseLeave={() => setHover(null)}
                />
              );
            }
            const x0 = ML + i * band + inset;
            if (stacks) {
              let prev = 0;
              return shown.map((s, si) => {
                const v = s.values[i] ?? 0;
                const y1 = yV(prev + v);
                const y2 = yV(prev);
                prev += v;
                return (
                  <rect
                    key={`${label}-${s.name}`}
                    {...mark(si)}
                    x={x0}
                    y={y1}
                    width={barThick}
                    height={Math.max(0, y2 - y1)}
                    onMouseEnter={() => setHover(i)}
                    onMouseLeave={() => setHover(null)}
                  />
                );
              });
            }
            const v = values[0] ?? 0;
            return (
              <rect
                key={label}
                {...mark(0)}
                x={x0}
                y={yV(v)}
                width={barThick}
                height={Math.max(0, yV(0) - yV(v))}
                onMouseEnter={() => setHover(i)}
                onMouseLeave={() => setHover(null)}
              />
            );
          })}
          <line
            className={baseline.className}
            style={baseline.style}
            x1={ML}
            x2={horizontal ? ML : W - MR}
            y1={horizontal ? MT : yV(0)}
            y2={horizontal ? height - MB : yV(0)}
          />
          {tickLabels.map(
            (label, i) =>
              i % labelEvery === 0 && (
                <text
                  key={label}
                  className={axis.className}
                  style={axis.style}
                  x={horizontal ? ML - 6 : ML + i * band + band / 2}
                  y={horizontal ? MT + i * band + band / 2 + 3 : height - 4}
                  textAnchor={horizontal ? "end" : "middle"}
                >
                  {label}
                </text>
              ),
          )}
        </g>
      </svg>
      {unit && (
        <ChartLegend aria-hidden="true">
          <ChartLegendItem>{unit}</ChartLegendItem>
        </ChartLegend>
      )}
      {hover != null && tickLabels[hover] && (
        <ChartTip
          left={horizontal ? "50%" : `${((ML + hover * band + band / 2) / W) * 100}%`}
          top={horizontal ? `${((MT + hover * band) / height) * 100}%` : `${(yV(shown[0]?.values[hover] ?? 0) / height) * 100}%`}
          label={tickLabels[hover]}
          rows={shown.map((s) => ({ name: shown.length > 1 ? s.name : undefined, value: tip(s.values[hover] ?? 0) }))}
        />
      )}
      <SrTable caption="Chart data" labels={tickLabels} series={shown} />
    </ChartField>
  );
}

"use client";

import * as React from "react";
import {
  ChartField,
  ChartHead,
  ChartLegend,
  ChartLegendItem,
  ChartTip,
  ChartTitle,
  LegendSwatch,
  PLOT,
  SrTable,
  chartStyles,
  defaultFormat,
  scatterMark,
  ticksBetween,
  type ChartAnnotation,
  type ChartPoint,
} from "./frame";
import { rs } from "../rs";

export type ScatterChartProps = React.HTMLAttributes<HTMLDivElement> & {
  points: ChartPoint[];
  height?: number;
  unit?: string;
  xLabel?: string;
  yLabel?: string;
  xDomain?: [number, number];
  yDomain?: [number, number];
  grid?: boolean;
  ticks?: number;
  annotations?: ChartAnnotation[];
  valueFormat?: (n: number) => string;
  spot?: boolean | string;
};

function extent(values: number[], pad = 0.08): [number, number] {
  const lo = Math.min(...values);
  const hi = Math.max(...values);
  const span = hi - lo || 1;
  return [lo - span * pad, hi + span * pad];
}

export function ScatterChart({
  points,
  height = 204,
  unit,
  xLabel,
  yLabel,
  xDomain,
  yDomain,
  grid = true,
  ticks = 4,
  annotations = [],
  valueFormat,
  className,
  spot,
  ...props
}: ScatterChartProps) {
  const format = valueFormat ?? ((v: number) => defaultFormat(v));
  const [hover, setHover] = React.useState<number | null>(null);
  const { W, ML, MR, MT, MB } = PLOT;
  const plotW = W - ML - MR;
  const plotH = height - MT - MB;
  const xs = points.map((p) => p.x);
  const ys = points.map((p) => p.y);
  const [xMin, xMax] = xDomain ?? extent(xs);
  const [yMin, yMax] = yDomain ?? extent(ys);
  const yTicks = ticksBetween(yMin, yMax, ticks);
  const xTicks = ticksBetween(xMin, xMax, ticks);
  const toX = (x: number) => ML + ((x - xMin) / (xMax - xMin || 1)) * plotW;
  const toY = (y: number) => MT + plotH - ((y - yMin) / (yMax - yMin || 1)) * plotH;
  const groups = [...new Set(points.map((p) => p.group).filter(Boolean))] as string[];
  const active = hover != null ? points[hover] : null;

  const svg = rs(["rs-chart-svg"], chartStyles.svg);
  const plot = rs(["rs-chart-plot"], chartStyles.plot);
  const gridSx = rs(["rs-chart-grid"], chartStyles.grid);
  const axis = rs(["rs-chart-axis"], chartStyles.axis);
  const baseline = rs(["rs-chart-baseline"], chartStyles.baseline);
  const cursor = rs(["rs-chart-cursor"], chartStyles.cursor);
  const ann = rs(["rs-chart-ann"], chartStyles.ann);
  const mark = scatterMark(Boolean(spot));

  return (
    <ChartField spot={spot} className={className} {...props}>
      {(yLabel || xLabel) && (
        <ChartHead>
          {yLabel ? <ChartTitle>{yLabel}</ChartTitle> : <span />}
          {xLabel ? <ChartTitle>{xLabel}</ChartTitle> : null}
        </ChartHead>
      )}
      <svg className={svg.className} style={svg.style} viewBox={`0 0 ${W} ${height}`} role="img" aria-label="Scatter">
        <g className={plot.className} style={plot.style}>
          {grid &&
            yTicks.map((t) => (
              <g key={`yg-${t}`}>
                <line className={gridSx.className} style={gridSx.style} x1={ML} x2={W - MR} y1={toY(t)} y2={toY(t)} />
                <text className={axis.className} style={axis.style} x={ML - 6} y={toY(t) + 3.5} textAnchor="end">
                  {format(t)}
                </text>
              </g>
            ))}
          {grid &&
            xTicks.map((t) => (
              <line key={`xg-${t}`} className={gridSx.className} style={gridSx.style} x1={toX(t)} x2={toX(t)} y1={MT} y2={MT + plotH} />
            ))}
          <line className={baseline.className} style={baseline.style} x1={ML} x2={ML} y1={MT} y2={MT + plotH} />
          <line className={baseline.className} style={baseline.style} x1={ML} x2={W - MR} y1={MT + plotH} y2={MT + plotH} />
          {xTicks.map((t) => (
            <text key={`xl-${t}`} className={axis.className} style={axis.style} x={toX(t)} y={height - 4} textAnchor="middle">
              {format(t)}
            </text>
          ))}
          {annotations.map((a) => (
            <g key={`${a.at}-${a.label}`}>
              <line className={cursor.className} style={cursor.style} x1={toX(a.at)} x2={toX(a.at)} y1={MT} y2={MT + plotH} />
              <text className={ann.className} style={ann.style} x={toX(a.at) + 4} y={MT + 10}>
                {a.label}
              </text>
            </g>
          ))}
          {points.map((p, i) => (
            <circle
              key={i}
              className={mark.className}
              style={mark.style}
              cx={toX(p.x)}
              cy={toY(p.y)}
              r={hover === i ? 3.5 : 2.25}
              onMouseEnter={() => setHover(i)}
              onMouseLeave={() => setHover(null)}
            />
          ))}
        </g>
      </svg>
      {active && (
        <ChartTip
          left={`${(toX(active.x) / W) * 100}%`}
          top={`${(toY(active.y) / height) * 100}%`}
          label={active.label ?? `${format(active.x)} · ${format(active.y)}`}
          rows={[{ name: active.group, value: format(active.y) }]}
        />
      )}
      {(groups.length > 0 || unit) && (
        <ChartLegend aria-hidden="true">
          {groups.map((g) => (
            <ChartLegendItem key={g}>
              <LegendSwatch seriesIndex={0} spot={Boolean(spot)} />
              {g}
            </ChartLegendItem>
          ))}
          {unit ? <ChartLegendItem>{unit}</ChartLegendItem> : null}
        </ChartLegend>
      )}
      <SrTable
        caption="Scatter data"
        labels={points.map((p) => p.label ?? `${p.x}`)}
        series={[{ name: "y", values: points.map((p) => p.y) }]}
      />
    </ChartField>
  );
}

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster } from "../tokens.stylex";
import { rs } from "../rs";
import { ChartField, ChartLegend, ChartLegendItem, ChartTitle, chartStyles, defaultFormat } from "./frame";

const styles = stylex.create({
  donut: {
    display: "block",
  },
  track: {
    fill: "none",
    stroke: raster.divider,
    strokeWidth: 1,
  },
  value: {
    fill: "none",
    stroke: "var(--rs-chart-spot)",
    strokeWidth: 1,
    strokeLinecap: "butt",
  },
  label: {
    fill: raster.ink,
    fontSize: 12,
    fontWeight: 500,
    letterSpacing: "-0.03em",
    fontVariantNumeric: "tabular-nums",
  },
  caption: {
    fill: raster.gray,
    fontSize: 8,
    fontWeight: 500,
    letterSpacing: "0.06em",
  },
  share: {
    display: "flex",
    height: 8,
    width: "100%",
    borderWidth: raster.hairline,
    borderStyle: "solid",
    borderColor: raster.divider,
    borderRadius: 0,
    boxShadow: "none",
  },
  seg: {
    height: "100%",
    borderRadius: 0,
    backgroundColor: {
      default: raster.ink,
      ":nth-child(2)": raster.gray,
      ":nth-child(3)": raster.divider,
    },
    transition: "fill var(--duration-snap) var(--ease), opacity var(--duration-snap) var(--ease)",
  },
  segSpot: {
